mapper.select:
SELECT distinct d.*, a.`name` AS name, a.axis AS axis, a.date as date, a.supplier as supplier, a.type AS area_type
FROM plan_detail AS d LEFT JOIN plan_area AS a ON d.area_id = a.id and a.bool_delete_enum = 0 WHERE d.bool_delete_enum = 0
and d.project_id = #{projectId}
and d.monomer_id = #{monomerId}
and d.area_product_type = #{areaProductType}
AND d.type = #{type}

SELECT
MIN(start_date) start_date,
MAX(end_date) end_date
FROM plan_detail
WHERE bool_delete_enum = 0

    AND monomer_id = #{monomerId}


    AND area_product_type = #{areaProductType}


    AND area_id = #{areaId}


    AND type = #{planType}
